function matchStyles(
  node: HTMLElement,
  delta: Delta,
  scroll: ScrollBlot,
) {
  const formats: Record<string, unknown> = {};
  const style: Partial<CSSStyleDeclaration> = node.style || {};
  if (style.fontStyle === 'italic') {
    formats.italic = true;
  }
  if (style.textDecoration === 'underline') {
    formats.underline = true;
  }
  if (style.textDecoration === 'line-through') {
    formats.strike = true;
  }
  if (
    style.fontWeight?.startsWith('bold') ||
    // @ts-expect-error Fix me later
    parseInt(style.fontWeight, 10) >= 700
  ) {
    formats.bold = true;
  }
  // Only apply formats that are registered in the editor's registry
  const supportedFormats: Record<string, unknown> = {};
  Object.keys(formats).forEach((key) => {
    if (scroll.query(key, Scope.INLINE) != null) {
      supportedFormats[key] = formats[key];
    }
  });
  if (Object.keys(supportedFormats).length > 0) {
    delta = applyFormat(delta, supportedFormats);
  }
  // @ts-expect-error
  if (parseFloat(style.textIndent || 0) > 0) {
    // Could be 0.5in
    return new Delta().insert('\t').concat(delta);
  }
  return delta;
}

